import whisper
import json
import re

FILLER_WORDS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "basically", "well", "okay"
}

FILLER_PHRASES = [
    "you know", "i mean", "kind of", "i guess"
]

def clean_word(word):
    return re.sub(r'[^\w]', '', word.lower().strip())

def detect_fillers(video_path, output_path):
    # Use tiny model for speed
    model = whisper.load_model("tiny")

    print(f"Transcribing {video_path}...")
    result = model.transcribe(video_path, word_timestamps=True, language="en")

    words_info = []
    for segment in result["segments"]:
        for word_info in segment.get("words", []):
            words_info.append({
                "word": word_info["word"],
                "clean": clean_word(word_info["word"]),
                "start": word_info["start"],
                "end": word_info["end"]
            })

    fillers = []

    # Check for phrases first (to avoid double counting if a phrase contains a filler word)
    # Actually, the user wants ALL filler words detected.
    # If "you know" is detected, should "you" or "know" be detected if they were filler?
    # Usually "you know" is the filler phrase.

    i = 0
    while i < len(words_info):
        matched_phrase = False
        for phrase in FILLER_PHRASES:
            phrase_words = phrase.split()
            phrase_len = len(phrase_words)

            if i + phrase_len <= len(words_info):
                segment_words = [w["clean"] for w in words_info[i:i+phrase_len]]
                if segment_words == phrase_words:
                    fillers.append({
                        "word": phrase,
                        "timestamp": round(words_info[i]["start"], 2)
                    })
                    i += phrase_len
                    matched_phrase = True
                    break

        if not matched_phrase:
            if words_info[i]["clean"] in FILLER_WORDS:
                fillers.append({
                    "word": words_info[i]["clean"],
                    "timestamp": round(words_info[i]["start"], 2)
                })
            i += 1

    with open(output_path, "w") as f:
        json.dump(fillers, f, indent=2)

    print(f"Detected {len(fillers)} filler words/phrases.")
    return fillers

if __name__ == "__main__":
    detect_fillers("/root/input.mp4", "/root/annotations.json")

